/* Collapsed sidebar tooltips */
.campus-sidebar.collapsed .sidebar-nav-link:hover::after {
  content: attr(data-tooltip);
  position: absolute;
  left: calc(100% + 12px);
  top: 50%;
  transform: translateY(-50%);
  background: rgba(15, 20, 40, 0.95);
  border: 1px solid rgba(99, 102, 241, 0.2);
  border-radius: 8px;
  padding: 6px 12px;
  font-size: 12.5px;
  font-weight: 600;
  color: #e0e7ff;
  white-space: nowrap;
  z-index: 9999;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);
  pointer-events: none;
}

/* ═══════════════════════════════════════════════════════════════════════
   Theme Toggle Animation
   ═══════════════════════════════════════════════════════════════════════ */
@keyframes themeToggleFadeIn {
  from { opacity: 0; transform: translateY(4px) scale(0.97); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

/* ═══════════════════════════════════════════════════════════════════════
   Light Theme Overrides — Arctic Light
   ═══════════════════════════════════════════════════════════════════════ */
[data-theme="light"] body,
:root[data-theme="light"] ~ body {
  background: #f8fafc !important;
  background-image:
    radial-gradient(ellipse at 15% 0%, rgba(139, 92, 246, 0.06) 0%, transparent 50%),
    radial-gradient(ellipse at 85% 100%, rgba(139, 92, 246, 0.04) 0%, transparent 50%),
    radial-gradient(ellipse at 50% 50%, rgba(255, 255, 255, 1) 0%, #f8fafc 100%) !important;
}

